"for f in AlgebraicJacobian/Picard/JacobianDataAbelImage.lean AlgebraicJacobian/Picard/JacobianDataAbelEffective.lean AlgebraicJacobian/Picard/JacobianDataAbelDegreeWindow.lean AlgebraicJacobian/Picard/JacobianDataAbel.lean AlgebraicJacobian/Picard/Pic0PullbackGrp.lean; do echo \"$f\"; nl -ba \"$f\" | sed -n '1,40p'; done",
"rg -n 'JacobianDataFromPicRepDatum|toJacobianData|PicRepDatum' AlgebraicJacobian.lean AlgebraicJacobian/Picard/Pic0CriticalPath.lean",
"rg -n 'def pullbackHom|theorem pullbackHom_id|theorem pullbackHom_comp' AlgebraicJacobian/Picard/Pic0PullbackGrp.lean",
"rg -n --glob '*.lean' 'smoothOfRelativeDimension_genus|exists_unique_ofCurve_comp|baseChangeIso|ofCurve' AlgebraicJacobian/Picard AlgebraicJacobian/AbelianVariety AlgebraicJacobian/Albanese | sed -n '1,260p'"
]; const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:40000}))); text(rs.map((r,i)=>"## "+i+"\n"+r.output).join("\n"));
